<!doctype html>
<html lang="pt-BR">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Formulário 5</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body><div class="container py-3"><div class="col-md-8 mx-auto"><h1 class="h3">Endereço de Cobrança</h1><form method="post">
<div class="row mb-3"><div class="col-md-6"><label for="primeiro_nome" class="form-label">Primeiro Nome</label><input type="text" id="primeiro_nome" name="primeiro_nome" class="form-control"></div><div class="col-md-6"><label for="ultimo_nome" class="form-label">Último Nome</label><input type="text" id="ultimo_nome" name="ultimo_nome" class="form-control"></div></div>
<div class="mb-3"><label for="usuario" class="form-label">Usuário</label><div class="input-group"><span class="input-group-text">@</span><input type="text" id="usuario" name="usuario" class="form-control" placeholder="Usuário"></div></div><div class="mb-3"><label for="email" class="form-label">E-mail</label><input type="email" id="email" name="email" class="form-control" placeholder="voce@exemplo.com"></div><div class="mb-3"><label for="endereco" class="form-label">Endereço</label><input type="text" id="endereco" name="endereco" class="form-control" placeholder="Rua Principal, 123"></div><div class="mb-3"><label for="complemento" class="form-label">Complemento</label><input type="text" id="complemento" name="complemento" class="form-control" placeholder="Apartamento ou bloco"></div>
<div class="row"><div class="col-md-5"><label for="pais" class="form-label">País</label><select id="pais" name="pais" class="form-select"><option selected>Selecione</option></select></div><div class="col-md-4"><label for="estado" class="form-label">Estado</label><select id="estado" name="estado" class="form-select"><option selected>Selecione</option></select></div><div class="col-md-3"><label for="cep" class="form-label">CEP</label><input type="text" id="cep" name="cep" class="form-control"></div></div>
</form></div></div></body></html>
